-- pg_schema.sql —— ChatBI SQLite -> PostgreSQL 平移版 schema（W1 D1 派单1 交付）
-- 用法：docker start pg 后，docker exec -i pg psql -U postgres < pg_schema.sql
-- 方言决策（两条，面试可讲）：
--   1) SQLite 的 INTEGER PRIMARY KEY 是 rowid 别名，隐式自增；
--      PG 必须显式声明。用 GENERATED BY DEFAULT AS IDENTITY 而不是 ALWAYS——
--      ALWAYS 禁止显式插入 id 值（seed 灌数会直接报错），BY DEFAULT 两者都允许。
--   2) SQLite 的 REAL 是 8 字节 IEEE 浮点（不是 4 字节）→ 映射 DOUBLE PRECISION 保真，
--      否则评测集里 ROUND 精度对比会因浮点误差掉分。
--   3) stat_date / fault_date 等日期列保持 TEXT（YYYY-MM-DD）：
--      最小改动原则——SQLite 原版就是 TEXT，text2sql.py 的 prompt 与日期函数按 TEXT 写，
--      平移不改语义，31 题评测才不会因方言漂移。

SELECT 'CREATE DATABASE chatbi'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'chatbi')\gexec

\c chatbi

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS dim_plant (
    plant_id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plant_name          TEXT    NOT NULL,
    province            TEXT    NOT NULL,
    region              TEXT    NOT NULL,
    station_type        TEXT    NOT NULL,
    capacity_mw         DOUBLE PRECISION NOT NULL,
    inverter_brand      TEXT    NOT NULL,
    inverter_efficiency DOUBLE PRECISION NOT NULL,
    grid_connect_date   TEXT    NOT NULL
);

CREATE TABLE IF NOT EXISTS fact_daily_generation (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plant_id           INTEGER NOT NULL,
    stat_date          TEXT    NOT NULL,
    generation_kwh     DOUBLE PRECISION NOT NULL,
    irradiation        DOUBLE PRECISION NOT NULL,
    equivalent_hours   DOUBLE PRECISION NOT NULL,
    curtailment_kwh    DOUBLE PRECISION NOT NULL,
    curtailment_rate   DOUBLE PRECISION NOT NULL
);

CREATE TABLE IF NOT EXISTS dim_device (
    device_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plant_id     INTEGER NOT NULL,
    device_type  TEXT    NOT NULL,
    device_model TEXT    NOT NULL
);

CREATE TABLE IF NOT EXISTS fact_device_fault (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    device_id       INTEGER NOT NULL,
    plant_id        INTEGER NOT NULL,
    fault_date      TEXT    NOT NULL,
    fault_type      TEXT    NOT NULL,
    downtime_minutes INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS metric_glossary (
    metric_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    metric_name TEXT    NOT NULL,
    aliases     TEXT,
    definition  TEXT    NOT NULL,
    formula     TEXT    NOT NULL,
    unit        TEXT,
    source_doc  TEXT
);

-- SQLite 原版无索引；PG 上补一个主查询模式索引（纯增益，不影响结果）
CREATE INDEX IF NOT EXISTS idx_fdg_plant_date ON fact_daily_generation (plant_id, stat_date);
